function Logo({ small = false }) { return <span className="inline-flex items-center gap-2.5"><span className="grid h-10 w-10 place-items-center rounded-2xl bg-teal-600 text-white shadow-lg shadow-teal-600/20"><HeartPulse size={22} /></span><span className="font-extrabold tracking-tight text-slate-800">HEALTHSYNC<span className="text-teal-600">-AI</span>{!small && <small className="block text-[9px] font-bold tracking-[.22em] text-slate-400">YOUR HEALTH, IN CONTEXT</small>}</span></span> }
function Button({ children, onClick, type = 'button', variant = 'primary', disabled = false, className = '' }) { const variants = { primary: 'bg-teal-600 text-white shadow-lg shadow-teal-700/15 hover:bg-teal-700', secondary: 'border border-slate-200 bg-white text-slate-700 hover:border-teal-300 hover:text-teal-700', ghost: 'text-slate-600 hover:bg-slate-100', soft: 'bg-teal-50 text-teal-700 hover:bg-teal-100' }; return <button type={type} onClick={onClick} disabled={disabled} className={`inline-flex items-center justify-center gap-2 rounded-xl px-4 py-3 text-sm font-bold transition ${variants[variant]} disabled:cursor-not-allowed ${className}`}>{children}</button> }
