  async function upload(e) { e.preventDefault(); await act(null, async () => { if (!file) throw Error('Choose a PDF, image, lab report, or prescription first.'); const f = new FormData(); f.append('file', file); f.append('title', title.trim() || file.name); f.append('record_type', kind); f.append('use_cloud_ocr', String(useCloudOcr)); f.append('use_openrouter_summary', String(useOpenRouterSummary)); const { data } = await api.post('/medical-records', f); setMessage(`${data.title} uploaded. ${data.extracted_text ? `Text extracted with ${data.extracted_data?.extraction_method === 'openrouter_vision_ocr' ? 'OpenRouter vision OCR' : data.extracted_data?.extraction_method === 'huggingface_vision_ocr' ? 'Hugging Face vision OCR' : data.extracted_data?.extraction_method || 'the available OCR pipeline'}; ${data.extracted_data?.structured_extraction_method === 'huggingface_qwen_extractor' ? 'Hugging Face Qwen fields' : 'baseline structured fields'} saved for review; ${data.extracted_data?.summary_method === 'huggingface_ai' ? 'Hugging Face AI summary' : data.extracted_data?.summary_method === 'openrouter_ai' ? 'OpenRouter AI summary' : 'local extractive summary'} saved.` : 'File stored, but no readable text was detected; check the original or retry with an enabled vision parser.'}`); setFile(null); setTitle(''); setUseCloudOcr(true); setUseOpenRouterSummary(true); if (uploadInputRef.current) uploadInputRef.current.value = ''; await load() }) }
