  async function scanVaccine(e) { e.preventDefault(); await act(null, async () => { if (!vaxFile) throw Error('Choose a vaccination card photo or PDF first.'); const form = new FormData(); form.append('file', vaxFile); form.append('use_cloud_ocr', String(vaxCloudOcr)); const { data } = await api.post('/vaccinations/scan', form); const sug = data.suggestions || {}; window._healthsyncScanRecord = data.record?.id || null; setVaccineDraft(prev => ({ ...prev, name: sug.suggested_name || prev.name, dose: sug.suggested_dose || prev.dose, date_received: sug.suggested_date_received || prev.date_received, next_due: sug.suggested_next_due || prev.next_due, notes: `Imported from ${vaxFile.name}. Review against the original card before saving.` })); setMessage(`Card stored in Medical records. Review the editable suggestions below. ${sug.suggested_name ? 'A vaccine name was suggested.' : 'No vaccine name could be confidently detected; enter it manually.'}`); setVaxFile(null); setVaxCloudOcr(true); if (vaccineInputRef.current) vaccineInputRef.current.value = ''; await load() }) }
