  async function saveRecordEdit(e) { await act(e, async () => { if (!editRecord?.id) return; await api.patch(`/medical-records/${editRecord.id}`, { title: editRecord.title, record_type: editRecord.record_type, provider_name: editRecord.provider_name || null, doctor_name: editRecord.doctor_name || null, record_date: editRecord.record_date || null }); setEditRecord(null); setMessage('Medical record details updated.'); await load() }) }
  async function openOriginal(r, download = false) {
    // Open a blank tab synchronously during the click so popup blockers do not
    // treat the later blob URL navigation as an unsolicited popup.
    const previewWindow = download ? null : window.open('about:blank', '_blank');
    if (!download && !previewWindow) {
      setError('Your browser blocked the original-document preview. Allow pop-ups for this local HEALTHSYNC-AI site and try again.');
      return;
    }
    if (previewWindow) {
      try {
        previewWindow.opener = null;
        previewWindow.document.title = 'Opening medical record…';
        previewWindow.document.body.innerHTML = '<p style="font:16px system-ui;padding:24px;color:#334155">Loading original medical document…</p>';
      } catch (_) { /* The document may already be navigating in some browsers. */ }
    }
    await act(null, async () => {
      try {
        const { data } = await api.get(`/medical-records/download/${r.id}`, { responseType: 'blob' });
        const extension = (r.original_filename || '').split('.').pop().toLowerCase();
        const mimeByExtension = { pdf: 'application/pdf', png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', webp: 'image/webp', tif: 'image/tiff', tiff: 'image/tiff' };
        const blob = data.type ? data : new Blob([data], { type: mimeByExtension[extension] || 'application/octet-stream' });
        const url = URL.createObjectURL(blob);
        if (download) {
          const a = document.createElement('a');
          a.href = url;
          a.download = r.original_filename || 'medical-record';
          document.body.appendChild(a); a.click(); a.remove();
          setTimeout(() => URL.revokeObjectURL(url), 60000);
        } else if (previewWindow && !previewWindow.closed) {
          previewWindow.location.replace(url);
          // Do not revoke on the initial navigation: the browser PDF viewer may
          // still be loading pages lazily. Revoke later to avoid an app-lifetime leak.
          setTimeout(() => URL.revokeObjectURL(url), 30 * 60 * 1000);
        } else {
          URL.revokeObjectURL(url);
          throw new Error('The preview tab was closed before the file loaded. Try Open original again.');
        }
      } catch (err) {
        if (previewWindow && !previewWindow.closed) previewWindow.close();
        throw err;
      }
    });
  }
