  function handleVerifiedItem(payload) {
    setEvidenceReport(previous => {
      if (!previous || previous.record_id !== payload.record_id) return previous;
      const next = JSON.parse(JSON.stringify(previous));
      const status = payload.verification_summary?.record_status;
      next.verification_status = status || next.verification_status;
      if (payload.item_type === 'candidate' && next.candidate_values?.[payload.index]) next.candidate_values[payload.index] = payload.item;
      else if (payload.item_type === 'medicine' && next.clinical_analysis?.medicines?.[payload.index]) next.clinical_analysis.medicines[payload.index] = payload.item;
      else if (payload.item_type === 'test' && next.clinical_analysis?.tests_and_results?.[payload.index]) next.clinical_analysis.tests_and_results[payload.index] = payload.item;
      else if (payload.item_type === 'instruction' && payload.section && next.clinical_analysis?.documented_instructions?.[payload.section]?.[payload.index]) next.clinical_analysis.documented_instructions[payload.section][payload.index] = payload.item;
      return next;
    });
    setRecords(previous => previous.map(record => {
      if (record.id !== payload.record_id) return record;
      const next = { ...record, extracted_data: JSON.parse(JSON.stringify(record.extracted_data || {})) };
      const data = next.extracted_data;
      if (payload.item_type === 'candidate' && data.candidates?.[payload.index]) data.candidates[payload.index] = payload.item;
      else if (payload.item_type === 'medicine' && data.clinical_analysis?.medicines?.[payload.index]) data.clinical_analysis.medicines[payload.index] = payload.item;
      else if (payload.item_type === 'test' && data.clinical_analysis?.tests_and_results?.[payload.index]) data.clinical_analysis.tests_and_results[payload.index] = payload.item;
      else if (payload.item_type === 'instruction' && payload.section && data.clinical_analysis?.documented_instructions?.[payload.section]?.[payload.index]) data.clinical_analysis.documented_instructions[payload.section][payload.index] = payload.item;
      next.verification_status = payload.verification_summary?.record_status || next.verification_status;
      return next;
    }));
    load();
  }
  async function review(id) { const useOpenRouter = window.confirm('Run AI medical extraction? Hugging Face via HF_TOKEN is used first; OpenRouter is a fallback if configured. The extracted OCR text and record title/type may be sent to that hosted provider. If OCR quality is low, the original scanned page may also be sent for re-reading. This includes sensitive health information. Choose Cancel for local evidence review only.'); setBusy(true); setError(''); try { const { data } = await api.post(`/evidence/analyze/${id}`, {}, { params: { use_openrouter: useOpenRouter } }); setEvidenceReport(data); setSummary(''); setAiAnswer(''); setAiSources([]); await load(); setTab('assistant'); setMessage(data.clinical_analysis?.status === 'complete' ? 'AI extraction finished. Review the structured medicine and care sections against the original document.' : 'Evidence review is ready; AI extraction was not run, or it needs configuration/retry. Check all items against the original.') } catch (e) { setError(errorText(e)) } finally { setBusy(false) } }
  const timeline = useMemo(() => [...records.map(r => ({ id: `r-${r.id}`, date: r.record_date || r.created_at, title: r.title || 'Medical record', detail: r.record_type || 'Document', icon: FileText })), ...vaccines.map(v => ({ id: `v-${v.id}`, date: v.date_received || v.created_at, title: v.name || 'Vaccination', detail: 'Immunization record', icon: Syringe })), ...reminders.map(r => ({ id: `m-${r.id}`, date: r.due_at, title: r.title, detail: r.is_completed ? 'Reminder completed' : 'Follow-up reminder', icon: Bell }))].sort((a, b) => new Date(b.date || 0) - new Date(a.date || 0)), [records, vaccines, reminders]);
  const todayKey = new Date().toLocaleDateString('en-CA');
